CREATE TABLE `file_assets` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`category` ENUM('evidence','export','attachment') NOT NULL,`relative_path` VARCHAR(768) NOT NULL,`content_sha256` CHAR(64) CHARACTER SET ascii NOT NULL,`size_bytes` BIGINT UNSIGNED NOT NULL,`status` ENUM('active','quarantined','deleted') NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_file_asset_org_path` (`organization_id`,`relative_path`(191)),KEY `idx_file_asset_scope_status` (`organization_id`,`workspace_id`,`status`,`updated_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
